#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
#include "../engine.h"

static int dns_init(engine_ctx_t *ctx)
{
    ctx->private_data = NULL;
    return ENGINE_OK;
}

static bool dns_can_handle(engine_ctx_t *ctx,
                                const session_entry_t *session,
                                const parsed_packet_t *pkt)
{
    (void)ctx;
    (void)session;
    if (!pkt || !pkt->payload || pkt->payload_len == 0) return false;

    /* TODO: 只做快速筛选，例如协议号、端口、payload 前几个字节。 */
    return false;
}

static int dns_process(engine_ctx_t *ctx,
                            session_entry_t *session,
                            const parsed_packet_t *pkt)
{
    (void)ctx;
    (void)session;
    if (!pkt || !pkt->payload || pkt->payload_len == 0) return ENGINE_CONTINUE;

    /* TODO: 在这里解析 dns 的关键特征。
     * 注意边界检查，不要在热路径做同步 I/O 或复杂阻塞操作。
     */

    return ENGINE_CONTINUE;
}

static void dns_cleanup(engine_ctx_t *ctx)
{
    if (ctx) ctx->private_data = NULL;
}

static const engine_ops_t dns_ops = {
    .name = "dns",
    .protocol_id = 0,      /* TODO: 按课程要求填写 */
    .priority = 200,       /* TODO: 根据插件链顺序调整 */
    .init = dns_init,
    .can_handle = dns_can_handle,
    .process = dns_process,
    .cleanup = dns_cleanup,
    .get_stats = NULL,
    .reset_stats = NULL,
};

const engine_ops_t* engine_get_ops(void)
{
    return &dns_ops;
}
